#!/usr/bin/env bash
# Renders the ambient sounds of a territory (wildlife per biome, settlement) from the game's .txtp files.
#
#     tools/linux/render_ambient.sh windsward
#
# Needs the .txtp files generated by tools/extract_audio.py in extract/_raw/txtp/ambient. Output
# extract/audio/ambient/<territory>/<type>_<biome>_<time>.ogg (imported by tools/ue/import_audio.py).
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
OGGENC="$ROOT/bin/oggenc"; [ -x "$OGGENC" ] || OGGENC="$(command -v oggenc)"
T="${1:?territory, e.g. windsward}"
OUT="$ROOT/extract/audio/ambient/$T"
mkdir -p "$OUT"
cd "$ROOT/extract/_raw/txtp/ambient"
n=0
for f in *"mx_territory=$T"*.txtp; do
    [ -e "$f" ] || continue
    name=$(echo "$f" | sed -E 's/play_quadamb_//; s/\(ext_int=amb_ext\) //; s/\(mx_territory=[a-z]+\) //; s/[()]//g;
        s/ /_/g; s/tract_state=//; s/tod_state=//; s/poi_state=//; s/\.txtp$//')
    [ -f "$OUT/$name.ogg" ] && continue
    nice "$ROOT/bin/vgmstream-cli" -i -p "$f" 2>/dev/null | nice "$OGGENC" -Q -q 4 -o "$OUT/$name.ogg" -
    n=$((n + 1))
done
echo "$n new sounds in $OUT ($(ls "$OUT" | wc -l) in total)"
